import React, { useEffect, useRef } from 'react';

export default function ProductSlider({ images=[], groups=[], id }){
  const trackRef = useRef(null);

  useEffect(()=>{ // drag to scroll
    const el = trackRef.current; if(!el) return;
    let isDown=false, startX=0, scrollLeft=0;
    const pt = (e)=> (e.touches ? e.touches[0].pageX : e.pageX);
    const down = e => { isDown=true; startX=pt(e) - el.offsetLeft; scrollLeft=el.scrollLeft; };
    const move = e => { if(!isDown) return; e.preventDefault(); const x=pt(e) - el.offsetLeft; el.scrollLeft = scrollLeft - (x - startX); };
    const up = ()=> isDown=false;
    el.addEventListener('mousedown', down); el.addEventListener('mousemove', move); window.addEventListener('mouseup', up);
    el.addEventListener('touchstart', down, {passive:true}); el.addEventListener('touchmove', move, {passive:false}); window.addEventListener('touchend', up);
    return ()=>{ el.removeEventListener('mousedown', down); el.removeEventListener('mousemove', move); window.removeEventListener('mouseup', up);
      el.removeEventListener('touchstart', down); el.removeEventListener('touchmove', move); window.removeEventListener('touchend', up); };
  }, []);

  const scrollBy = (px)=>{ trackRef.current?.scrollBy({ left: px, behavior: 'smooth' }); };
  const groupSlides = Array.isArray(groups) && groups.length>0;

  const slideForGroup = (g) => {
    const n = Math.min(Math.max((g.products||[]).length, 1), 4); // 1..4 para clases
    const cls = `ps-card pg-card pg-n-${n}`;
    return (
      <div className={cls} key={g.id}>
        <div className="pg-grid" style={{'--group-h':'28vh'}}>
          {(g.products||[]).map(p => (
            <a className="pg-item" key={p.id} href={`/producto/${p.id}`}>
              <img src={p.imageUrl || p.image || '/placeholder.png'} alt=""/>
            </a>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="ps-root ps-edge" id={id}>
      <button className="ps-nav prev" onClick={()=>scrollBy(-trackRef.current.clientWidth*0.9)}>‹</button>
      <div className="ps-track" ref={trackRef}>
        {groupSlides
          ? groups.map(slideForGroup)
          : images.map((src, i)=>(
              <a className="ps-card" key={i} href={`/producto/${src.id || i}`}>
                <img src={src.imageUrl || src} alt="" />
              </a>
            ))
        }
      </div>
      <button className="ps-nav next" onClick={()=>scrollBy(trackRef.current.clientWidth*0.9)}>›</button>
    </div>
  );
}
